"""Review complete action sequences from production Godot screenshots."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
STYLE = (ROOT / 'tools/build_action_motion_review.py').read_text().split('<style>')[1].split('</style>')[0]
page = '''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cổ Sư · Liên kết động tác 0.43</title><style>__STYLE__</style>
<main><h1>Chân giữ điểm tựa. Tay thu về liền mạch.</h1><p>0.43 · Xem cả chuỗi vào động tác, thao tác và trở lại di chuyển. Dụng cụ chuyển ở nhịp chuẩn bị / thu tay; khi bị ngắt, chỉ một vật cầm tay được vẽ tại mỗi thời điểm.</p>
<nav><a href="#world">Trong game</a><a href="concept43_transitions.json">Kiểm chuyển động</a><a href="concept42_action_review.html">Từng động tác & nguồn tham khảo · 0.42</a><a href="concept41_character_review.html">Asset theo hướng · 0.41</a></nav>
<div class="controls"><label>Chuỗi động tác<select id="action"><option value="sword">Vung kiếm → thu tay</option><option value="mine">Khai khoáng → cất cuốc</option><option value="cancel">Ngắt cuốc → đi → quay</option><option value="gather">Hái lượm → quay người</option></select></label><label>Giới tính<select id="body"><option value="0">Nam</option><option value="1">Nữ</option></select></label><label>Hướng xuất phát<select id="direction"></select></label><label>Tốc độ<select id="speed"><option value="1">Nhịp trong game · 1×</option><option value=".5">Chậm · ½×</option><option value=".25">Rất chậm · ¼×</option></select></label><label>Lớp xem<select id="bones"><option value="0">Hình nhân vật</option><option value="1">Khớp xương</option></select></label><button id="prev" aria-label="Frame trước">←</button><button id="play" disabled>Phát</button><button id="next" aria-label="Frame sau">→</button></div>
<div class="scrub"><input id="slider" type="range" min="0" max="35" value="12" aria-label="Chọn frame"><output id="count"></output></div>
<div class="detail"><div class="crop"><img id="focus" alt="Nhân vật trong chuỗi chuyển động"></div><div class="note"><h2 id="name"></h2><p id="status" role="status"></p><p id="motion"></p><p class="legend">Ảnh Godot thật ở 30 FPS, bước cập nhật animation 120 Hz. Bốn mốc xương mỗi chuỗi. Chọn “Ngắt cuốc” để kiểm đổi động tác giữa chừng; hướng hiển thị bên dưới là hướng thực tế của frame.</p><a id="original">Mở ảnh gốc đủ 16 góc</a></div></div><img class="full" id="full" alt="Nam và nữ ở tám hướng xuất phát">
<details id="world"><summary>Phím E trong game và xưởng nhân vật F6</summary><p>Thu thập và phần thưởng vẫn theo sự kiện game. Đi lại hoặc bị đánh sẽ ngắt động tác; không chờ hiệu ứng chuyển dụng cụ để điều khiển nhân vật.</p><img class="full" src="concept43_world_gather_30.png" alt="Hái lượm trong game"><img class="full" src="concept43_world_mine_30.png" alt="Cuốc khoáng trong game"><a href="concept43_ingame.json">Kiểm input E / F6</a></details></main>
<script>
const clips=__CLIPS__, $=id=>document.getElementById(id), dirs=['S · xuống','SW · xuống trái','W · trái','NW · lên trái','N · lên','NE · lên phải','E · phải','SE · xuống phải'];
const notes={sword:'Chân được giải lại từ điểm đặt trên mặt đất khi pha sang tư thế nghỉ; khớp gối không kéo bàn chân theo một cung tròn.',mine:'Kiếm khuất dần khi chuẩn bị, cuốc hiện trước nhịp bổ; thu tay xong mới trả lại vũ khí đang trang bị.',cancel:'Ngắt giữa lúc giơ cuốc để đi, rồi quay 90°. Cuốc vẫn bám bàn tay khi rời khung; tay giơ không đổi lớp đè lên mặt.',gather:'Hái cây, thu tay và quay 180°. Mỗi góc dùng điểm chân và hướng gập gối của chính hình chiếu đó.'};
const actions={idle:'Đứng',walk:'Đi',attack:'Vung kiếm',mine:'Khai khoáng',gather:'Hái lượm'}, props={none:'Tay trống',sword:'Kiếm',pick:'Cuốc',spear:'Thương'};
let timer=null,frame=12,generation=0;const loaded=new Set();dirs.forEach((text,d)=>$('direction').add(new Option(text,d)));$('direction').value='6';
function url(n,bones=false){return bones?`concept43_${$('action').value}_bones_${String(n).padStart(2,'0')}.png`:`concept43_${$('action').value}/frame${String(n).padStart(3,'0')}.png`}
function update(){const a=$('action').value,clip=clips[a],b=+$('body').value,d=+$('direction').value,overlay=$('bones').value==='1';frame=Math.min(frame,clip.frames-1);let n=frame;if(overlay)n=[6,12,24,30].reduce((best,x)=>Math.abs(x-frame)<Math.abs(best-frame)?x:best,6);const state=clip.states[n][b*8+d],source=url(n,overlay);$('focus').src=$('full').src=$('original').href=source;$('focus').style.left=`${-d*320}px`;$('focus').style.top=`${-(105+b*370)}px`;$('slider').max=clip.frames-1;$('slider').value=frame;$('count').textContent=`${n+1} / ${clip.frames}`;$('name').textContent=`${b?'Nữ':'Nam'} · ${dirs[state.direction]} · ${actions[state.action]}`;$('status').textContent=`${(n/30).toFixed(2)} / ${clip.duration.toFixed(2)} giây · ${props[state.prop.kind]}${state.prop.opacity<.99?' · chuyển dụng cụ':''}${overlay?' · mốc xương gần nhất':''}`;$('motion').textContent=notes[a];}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Phát'}
function step(delta){const n=clips[$('action').value].frames;frame=(frame+delta+n)%n;update()}
async function prepare(){const a=$('action').value,gen=++generation;$('play').disabled=true;if(!loaded.has(a)){await Promise.all(Array.from({length:clips[a].frames},(_,n)=>new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src=`concept43_${a}/frame${String(n).padStart(3,'0')}.png`})));loaded.add(a)}if(gen===generation)$('play').disabled=false}
function play(){if(timer){stop();return}timer=setInterval(()=>step(1),1000/30/+$('speed').value);$('play').textContent='Dừng'}
$('play').onclick=play;$('prev').onclick=()=>{stop();step(-1)};$('next').onclick=()=>{stop();step(1)};$('slider').oninput=()=>{stop();frame=+$('slider').value;update()};for(const id of ['action','body','direction','bones'])$(id).onchange=()=>{stop();update();if(id==='action')prepare().catch(()=>{$('status').textContent='Không tải được một số frame.'})};$('speed').onchange=()=>{if(timer){stop();play()}};document.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();if(!$('play').disabled)play()}if(e.key==='ArrowRight'){stop();step(1)}if(e.key==='ArrowLeft'){stop();step(-1)}});update();prepare().catch(()=>{$('status').textContent='Không tải được frame. Hãy tải lại trang.'});
</script></html>'''
if __name__ == '__main__':
    report = json.loads((ROOT / 'artifacts/concept43_native.json').read_text())
    (ROOT / 'artifacts/concept43_transition_review.html').write_text(page.replace('__STYLE__', STYLE).replace('__CLIPS__', json.dumps(report['clips'], ensure_ascii=False)))
    print('Built character transition review 0.43')
